from typing import List


def parse_nested_parens(paren_string: str) -> List[int]:
    depths = []
    for group in paren_string.split():
        max_depth = 0
        current_depth = 0
        for char in group:
            if char == '(':  
                current_depth += 1
                max_depth = max(max_depth, current_depth)
            elif char == ')':
                current_depth -= 1
        depths.append(max_depth)
    return depths

from typing import List, Tuple

def sum_product(numbers: List[int]) -> Tuple[int, int]:
    total_sum = sum(numbers)
    total_product = 1
    for number in numbers:
        total_product *= number
    return (total_sum, total_product) if numbers else (0, 1)

from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    count = {}
    # Count occurrences of each number
    for number in numbers:
        count[number] = count.get(number, 0) + 1
    # Filter out numbers that occur more than once
    return [number for number in numbers if count[number] == 1]

def fizz_buzz(n: int):
    count = 0
    for i in range(n):
        if i % 11 == 0 or i % 13 == 0:
            count += str(i).count('7')
    return count

def monotonic(l: list):
    """Return True is list elements are monotonically increasing or decreasing."""
    if not l:
        return True
    increasing = decreasing = True
    for i in range(1, len(l)):
        if l[i] > l[i - 1]:
            decreasing = False
        elif l[i] < l[i - 1]:
            increasing = False
    return increasing or decreasing

def largest_prime_factor(n: int):
    """Return the largest prime factor of n. Assume n > 1 and is not a prime."""
    # Start with the smallest prime factor
    factor = 2
    # Continue dividing n by factor until it becomes 1
    while n > 1:
        if n % factor == 0:
            n //= factor  # Divide n by the factor
        else:
            factor += 1  # Move to the next potential factor
    return factor  # The last factor will be the largest prime factor

def correct_bracketing(brackets: str):
    count = 0
    for char in brackets:
        if char == '(':  
            count += 1
        elif char == ')':
            count -= 1
        if count < 0:
            return False
    return count == 0

def total_match(lst1, lst2):
    total_chars_lst1 = sum(len(s) for s in lst1)
    total_chars_lst2 = sum(len(s) for s in lst2)
    if total_chars_lst1 <= total_chars_lst2:
        return lst1
    return lst2

