def anti_shuffle(s):
    result = []
    i = 0
    while i < len(s):
        if s[i] == ' ':
            result.append(' ')
            i += 1
        else:
            start = i
            while i < len(s) and s[i] != ' ':
                i += 1
            sorted_word = ''.join(sorted(s[start:i]))
            result.append(sorted_word)
    return ''.join(result)

def next_smallest(lst):
    if len(lst) < 2:
        return None
    distinct_elements = sorted(set(lst))
    return distinct_elements[1] if len(distinct_elements) > 1 else None

def sum_squares(lst):
    total = 0
    for i, val in enumerate(lst):
        if i % 3 == 0 and val % 3 != 0:
            total += val ** 2
        elif i % 4 == 0 and val % 4 != 0:
            total += val ** 3
        else:
            total += val
    return total

def order_by_points(nums):
    """
    Write a function which sorts the given list of integers
    in ascending order according to the sum of their digits.
    Note: if there are several items with similar sum of their digits,
    order them based on their index in original list.

    For example:
    >>> order_by_points([1, 11, -1, -11, -12]) == [-1, -11, 1, -12, 11]
    >>> order_by_points([]) == []
    """
    def digit_sum(n):
        str_n = str(n)
        if n < 0:
            return -int(str_n[1]) + sum(int(d) for d in str_n[2:])
        return sum(int(d) for d in str_n)

    return sorted(nums, key=lambda x: (digit_sum(x), nums.index(x)))

def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
            return False
    return True

def x_or_y(n, x, y):
    """A simple program which should return the value of x if n is 
    a prime number and should return the value of y otherwise."""
    return x if is_prime(n) else y

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    even_count = 0
    odd_count = 0
    for digit in str(abs(num)):
        if int(digit) % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

import hashlib

def string_to_md5(text):
    """
    Given a string 'text', return its md5 hash equivalent string.
    If 'text' is an empty string, return None.

    >>> string_to_md5('Hello world') == '3e25960a79dbc69b674cd4ec67a72c62'
    """
    if text == '':
        return None
    return hashlib.md5(text.encode()).hexdigest()
